const { voxels } = api;
const v = voxels();

// Define a classic royal palette: "White Stone & Royal Blue Roofs"
const WATER = '#1d4ed8';         // Rich deep blue
const WATER_SHALLOW = '#60a5fa';   // Light blue ripples
const GRASS = '#166534';         // Deep forest green
const HEDGE = '#15803d';         // Vibrant hedge green
const STONE_LIGHT = '#cbd5e1';   // Silver grey stone
const STONE_DARK = '#475569';    // Slate charcoal stone
const STONE_WHITE = '#f8fafc';   // Pristine marble white trim
const ROOF = '#1e3a8a';          // Royal slate blue roofs
const ROOF_LIGHT = '#2563eb';    // Bright blue accents
const WOOD = '#451a03';          // Dark mahogany wood
const WOOD_LIGHT = '#78350f';    // Chestnut wood
const FLAG_GOLD = '#fbbf24';     // Golden crest
const FLAG_BLUE = '#2563eb';     // Royal blue banners
const FLAG_POLE = '#94a3b8';     // Steel pole
const WINDOW = '#a5f3fc';        // Glowing leaded glass
const FLOWERS = '#ec4899';       // Pink flowers in the garden

// Helper for face-connected 3D lines (prevents non-manifold edge-only contact)
function faceConnectedLine(grid, p0, p1, color) {
  let [x, y, z] = p0;
  const [x1, y1, z1] = p1;
  const dx = Math.sign(x1 - x);
  const dy = Math.sign(y1 - y);
  const dz = Math.sign(z1 - z);

  grid.set(x, y, z, color);
  while (x !== x1 || y !== y1 || z !== z1) {
    const distx = Math.abs(x1 - x);
    const disty = Math.abs(y1 - y);
    const distz = Math.abs(z1 - z);

    if (disty >= distx && disty >= distz) {
      y += dy;
    } else if (distz >= distx && distz >= disty) {
      z += dz;
    } else {
      x += dx;
    }
    grid.set(x, y, z, color);
  }
}

// 1. Water Moat Base (Z=0, 90x89: x=-45..44, y=-44..44)
v.fillBox([0, -44, 0], [44, 44, 0], WATER);

// Water highlights
v.set(22, -41, 0, WATER_SHALLOW);
v.set(41, -25, 0, WATER_SHALLOW);
v.set(10, 40, 0, WATER_SHALLOW);
v.set(42, 18, 0, WATER_SHALLOW);

// 2. Island Base (Z=1, 78x77: x=-39..38, y=-38..38)
v.fillBox([0, -38, 1], [38, 38, 1], GRASS);

// Grand stone arch bridge over the moat (Y = -44 to -37)
v.fillBox([0, -44, 1], [3, -37, 2], STONE_DARK);
v.fillBox([0, -42, 3], [3, -37, 3], STONE_LIGHT);
// Drawbridge chains (face-connected)
faceConnectedLine(v, [4, -34, 10], [3, -42, 4], FLAG_POLE);

// 3. Concentric Design: LOWER OUTER DEFENSE WALLS (Z=2 to 8, Y=-32 to 32, X=32)
// Outer right wall
v.fillBox([31, -31, 2], [32, 31, 8], STONE_LIGHT);
// Outer back wall
v.fillBox([0, 31, 2], [31, 32, 8], STONE_LIGHT);
// Outer front wall (leaves gap for gate)
v.fillBox([8, -32, 2], [31, -31, 8], STONE_LIGHT);

// Outer Wall Battlements & Walkway (Z=9)
// X=32 is battlement, X=31 is the walkway
for (let y = -31; y <= 31; y += 2) {
  v.set(32, y, 9, STONE_DARK);
}
for (let x = 1; x <= 31; x += 2) {
  v.set(x, 32, 9, STONE_DARK);
}
for (let x = 8; x <= 31; x += 2) {
  v.set(x, -32, 9, STONE_DARK);
}

// Outer gate lintel: closes the 2-voxel slot above the doors (x=-3..2 after mirroring)
v.fillBox([0, -32, 7], [2, -31, 8], STONE_LIGHT);

// Outer Corner Towers (Radius 3.5, Z=2 to 14)
v.cylinder([32, 32, 2], 3.5, 12, STONE_LIGHT);
v.cylinder([32, -32, 2], 3.5, 12, STONE_LIGHT);
// White marble tower crowns
v.cylinder([32, 32, 14], 3.7, 1, STONE_WHITE);
v.cylinder([32, -32, 14], 3.7, 1, STONE_WHITE);

// Outer Corner Tower Roofs (Slate-blue cones)
for (let h = 0; h <= 6; h++) {
  let r = Math.max(0, 4 - Math.floor(h * 0.7));
  v.cylinder([32, 32, 15 + h], r, 1, ROOF);
  v.cylinder([32, -32, 15 + h], r, 1, ROOF);
}

// Outer Gate Towers flanking the drawbridge (Z=2 to 12)
v.cylinder([5, -32, 2], 2.5, 10, STONE_LIGHT);
v.cylinder([5, -32, 12], 2.7, 1, STONE_WHITE);
for (let h = 0; h <= 4; h++) {
  let r = Math.max(0, 3 - Math.floor(h * 0.8));
  v.cylinder([5, -32, 13 + h], r, 1, ROOF);
}

// 4. Concentric Design: HIGHER INNER DEFENSE WALLS (Z=2 to 15, Y=-18 to 18, X=18)
// Inner right wall
v.fillBox([17, -17, 2], [18, 17, 15], STONE_LIGHT);
v.fillBox([17, -17, 8], [18, 17, 8], STONE_WHITE); // White trim belt
// Inner back wall
v.fillBox([0, 17, 2], [17, 18, 15], STONE_LIGHT);
v.fillBox([0, 17, 8], [17, 18, 8], STONE_WHITE);
// Inner front wall (leaving gap for inner gate)
v.fillBox([5, -18, 2], [17, -17, 15], STONE_LIGHT);
v.fillBox([5, -18, 8], [17, -17, 8], STONE_WHITE);
// Inner gate lintel: closes the wall above the door (gap is x=-5..4 after mirroring)
v.fillBox([0, -18, 8], [4, -17, 15], STONE_LIGHT);
v.fillBox([0, -18, 8], [4, -17, 8], STONE_WHITE);   // matches the trim belt

// Inner Wall Battlements (Z=16)
for (let y = -17; y <= 17; y += 2) {
  v.set(18, y, 16, STONE_DARK);
}
for (let x = 1; x <= 17; x += 2) {
  v.set(x, 18, 16, STONE_DARK);
}
for (let x = 1; x <= 17; x += 2) {   // runs on across the (now lintel-closed) inner gate
  v.set(x, -18, 16, STONE_DARK);
}

// Inner Corner Towers (Radius 4.5, Z=2 to 24)
v.cylinder([18, 18, 2], 4.5, 22, STONE_LIGHT);
v.cylinder([18, -18, 2], 4.5, 22, STONE_LIGHT);
// White marble battlements
v.cylinder([18, 18, 24], 4.8, 1, STONE_WHITE);
v.cylinder([18, -18, 24], 4.8, 1, STONE_WHITE);

// Inner Corner Tower Roofs (Cone Z=25 to 33)
for (let h = 0; h <= 8; h++) {
  let r = Math.max(0, 5 - Math.floor(h * 0.7));
  v.cylinder([18, 18, 25 + h], r, 1, ROOF);
  v.cylinder([18, -18, 25 + h], r, 1, ROOF);
}

// Flags on Inner Towers (poles Z=34 to 37, gold banners Z=36 to 37)
v.fillBox([18, 18, 34], [18, 18, 37], FLAG_POLE);
v.fillBox([18, 15, 36], [18, 17, 37], FLAG_GOLD);
v.fillBox([18, -18, 34], [18, -18, 37], FLAG_POLE);
v.fillBox([15, -18, 36], [17, -18, 37], FLAG_GOLD);   // front tower banner: gold, spans X so it faces the front camera

// 5. Grand Central Keep (The Monarch's Palace)
// Keep Base: X from 0 to 8, Y from -8 to 8, Z from 2 to 30 (Tall and majestic!)
v.fillBox([0, -8, 2], [8, 8, 30], STONE_LIGHT);

// Structural Corner Columns in White Marble
v.fillBox([7, -8, 2], [8, -7, 30], STONE_WHITE);
v.fillBox([7, 7, 2], [8, 8, 30], STONE_WHITE);

// Royal Cresting & Horizontal Belts (Z=12, Z=22)
v.fillBox([0, -8, 12], [8, 8, 12], STONE_DARK);
v.fillBox([0, -8, 22], [8, 8, 22], STONE_WHITE);

// Keep Balconies & Upper Deck
v.fillBox([0, -6, 31], [6, 6, 33], STONE_WHITE);
// Keep Battlements (Z=34)
for (let y = -6; y <= 6; y += 2) v.set(6, y, 34, STONE_DARK);
for (let x = 1; x <= 6; x += 2) {
  v.set(x, 6, 34, STONE_DARK);
  v.set(x, -6, 34, STONE_DARK);
}

// Grand Central Slate Spire (Centered on X=0, Y=0)
for (let h = 0; h <= 10; h++) {
  let r = Math.max(0, 4 - Math.floor(h * 0.4));
  v.cylinder([0, 0, 34 + h], r, 1, ROOF);
}
// Massive Golden Sovereign Flag (pole Z=44 to 50, banner Z=47 to 50)
v.fillBox([0, 0, 44], [0, 0, 50], FLAG_POLE);
v.fillBox([0, -4, 47], [0, -1, 50], FLAG_GOLD);

// 6. Courtyard Landscaping & Water Features
// Outer Courtyard Gardens (between inner and outer walls)
// Hedges
v.fillBox([24, -15, 2], [26, 15, 3], HEDGE);
// Cut pathways through hedges
for (let y = -3; y <= 3; y++) { // 7 wide: clears the whole footprint of the fountain basin (y=-3..3)
  for (let x = 24; x <= 26; x++) for (let z = 2; z <= 3; z++) v.remove(x, y, z); // clear (remove, not colour 0 = black)
}
v.fillBox([22, 0, 1], [28, 0, 1], STONE_DARK); // Garden path (under the fountain basin)
// Visible path legs: inner wall -> fountain -> outer wall, 3 wide so it reads from above
v.fillBox([19, -1, 1], [21, 1, 1], STONE_DARK);
v.fillBox([29, -1, 1], [30, 1, 1], STONE_DARK);

// Pink flowers dotted on the hedges
v.set(25, -12, 4, FLOWERS);
v.set(25, -6, 4, FLOWERS);
v.set(25, 6, 4, FLOWERS);
v.set(25, 12, 4, FLOWERS);

// Royal Water Fountain (X=25, Y=0, Z=2)
v.cylinder([25, 0, 2], 3, 1, STONE_WHITE);
v.cylinder([25, 0, 2], 2, 1, WATER);
v.fillBox([25, 0, 2], [25, 0, 4], STONE_WHITE); // Spout
v.set(25, 0, 5, WATER_SHALLOW); // Water jet
v.set(24, 0, 4, WATER_SHALLOW); // Droplets
v.set(26, 0, 4, WATER_SHALLOW);
v.set(25, 1, 4, WATER_SHALLOW);
v.set(25, -1, 4, WATER_SHALLOW);

// Courtyard trees
// (x=26 so each canopy stops at x=29, leaving a 1-voxel gap before the outer wall at x=31)
v.fillBox([26, -25, 2], [26, -25, 6], WOOD); // Left Tree
v.sphere([26, -25, 7], 3, HEDGE);
v.fillBox([26, 25, 2], [26, 25, 6], WOOD);  // Right Tree
v.sphere([26, 25, 7], 3, HEDGE);

// 7. Detailed Stained Glass Windows on the Keep & Towers
v.fillBox([8, -1, 15], [8, 1, 19], WINDOW); // Massive keep window
v.fillBox([8, -2, 14], [8, -2, 20], STONE_DARK); // Window framing
v.fillBox([8, 2, 14], [8, 2, 20], STONE_DARK);
v.fillBox([8, -1, 20], [8, 1, 20], STONE_DARK);
v.fillBox([8, -1, 14], [8, 1, 14], STONE_DARK);

// Other windows on the towers
v.fillBox([18, 9, 12], [18, 10, 14], WINDOW);    // on the straight inner wall, clear of the corner towers
v.fillBox([18, -10, 12], [18, -9, 14], WINDOW);

// Mossy ivy crawling up the walls of the Inner Keep
faceConnectedLine(v, [8, 5, 2], [8, 6, 18], HEDGE);
v.set(8, 4, 10, HEDGE);
v.set(8, 6, 14, HEDGE);                         // on the keep's outer face, beside the ivy line

// 8. Gates & Access Doors
// Outer Gate oak doors (Y=-32, X=0 to 4)
v.fillBox([0, -32, 2], [4, -32, 6], WOOD);
v.fillBox([0, -32, 4], [4, -32, 4], WOOD_LIGHT); // Metal reinforcement bar

// Inner Gate oak doors (Y=-18, X=0 to 4; mirrors to -5..4)
v.fillBox([0, -18, 2], [4, -18, 7], WOOD);   // x=0..4 mirrors to -5..4: fills the whole 10-wide gate gap

// Symmetrical replication
v.mirror('x');

return v;
